To make Dijkstra efficient, we combine it with a **priority queue (min-heap)**. The heap always gives us the next closest node.

```js
function dijkstra(graph, start) {
  const distances = {};
  const visited = new Set();
  const pq = new MinHeap();

  for (let node in graph) distances[node] = Infinity;
  distances[start] = 0;
  pq.insert({ node: start, dist: 0 });

  while (pq.heap.length) {
    const { node, dist } = pq.extractMin();
    if (visited.has(node)) continue;
    visited.add(node);

    for (let edge of graph[node]) {
      const newDist = dist + edge.weight;
      if (newDist < distances[edge.node]) {
        distances[edge.node] = newDist;
        pq.insert({ node: edge.node, dist: newDist });
      }
    }
  }

  return distances;
}
```

