How does direct access to shared state change the way you design components?

This example ties everything together into a real app pattern.

```js
// ThemeContext.js
import React from 'react';
export const ThemeContext = React.createContext();

// App.js
import React, { useState } from 'react';
import { View, Text } from 'react-native';
import { ThemeContext } from './ThemeContext';
import ThemedButton from './ThemedButton';

export default function App() {
  const [theme, setTheme] = useState('light');

  return (
    <ThemeContext.Provider value={{ theme, setTheme }}>
      <View style={{ flex: 1, justifyContent: 'center', alignItems: 'center' }}>
        <Text style={{ marginBottom: 20 }}>Current Theme: {theme}</Text>
        <ThemedButton />
      </View>
    </ThemeContext.Provider>
  );
}
```

This pattern is widely used for dark mode toggles, language switching, and accessibility settings.

